// Full storefront validation. Usage: node validate.js <out-dir> <label>
const { chromium } = require('playwright');
const fs = require('fs');
const B = 'http://127.0.0.1:8080', OUT = process.argv[2], LABEL = process.argv[3] || 'run';
const axeSrc = fs.readFileSync(__dirname + '/node_modules/axe-core/axe.min.js', 'utf8');
// Findings in markup generated by WooCommerce core (not by this theme), matched by rule AND element:
const IGNORE_AXE = [
  ['image-redundant-alt', ''],                         // WooCommerce block cart: product image alt = product name link text.
  ['aria-input-field-name', 'select2-'],               // WooCommerce selectWoo state/country combobox (classic checkout/address forms).
  ['heading-order', '.woocommerce-billing-fields > h3'], // WooCommerce classic checkout template uses h3 under the page h1.
];
const ignored = v => IGNORE_AXE.some(([id, sel]) => v.id === id && v.t.includes(sel));
let failures = 0;
(async () => {
  const b = await chromium.launch();
  const prods = await (await fetch(B + '/wp-json/wc/store/v1/products?per_page=50')).json();
  const url = n => prods.find(p => p.name === n).permalink;
  const gallery = url('منتج تجريبي أ'), simple = url('منتج تجريبي ج'), variable = url('منتج تجريبي ح');
  const pages = [
    ['home', '/'], ['shop', '/shop/'], ['categories', '/categories/'],
    ['category', '/product-category/%D8%A7%D9%84%D9%85%D8%B7%D8%A7%D8%A8%D8%AE/'],
    ['single-gallery', gallery], ['single-variable', variable],
    ['about', '/about/'], ['contact', '/contact/'], ['search', '/?s=%D9%85%D9%86%D8%AA%D8%AC&post_type=product'],
    ['404', '/nonexistent-page/', 404], ['blog', '/?post_type=post&s=%D9%85%D9%82%D8%A7%D9%84%D8%A9'],
    ['elementor-fullwidth', '/elementor-fw/'], ['account-login', '/my-account/'],
    // stateful
    ['cart-block', '/cart/', 200, 'cart'], ['checkout-block', '/checkout/', 200, 'cart'],
    ['cart-classic', '/cart-classic/', 200, 'cart'], ['checkout-classic', '/checkout-classic/', 200, 'cart'],
    ['acc-dashboard', '/my-account/', 200, 'login'], ['acc-orders', '/my-account/orders/', 200, 'login'],
    ['acc-addresses', '/my-account/edit-address/', 200, 'login'], ['acc-edit-billing', '/my-account/edit-address/billing/', 200, 'login'],
    ['acc-details', '/my-account/edit-account/', 200, 'login'],
  ];
  const rows = [];
  for (const [vn, w, h] of [['m', 390, 844], ['d', 1280, 900]]) {
    const ctx = await b.newContext({ viewport: { width: w, height: h } });
    const p = await ctx.newPage();
    const errs = []; p.on('pageerror', e => errs.push(e.message.slice(0, 150)));
    let carted = false, logged = false;
    for (const [name, path, expect = 200, need] of pages) {
      if (need === 'cart' && !carted) {
        await p.goto(simple, { waitUntil: 'networkidle' });
        await p.click('button.single_add_to_cart_button'); await p.waitForLoadState('networkidle'); carted = true;
      }
      if (need === 'login' && !logged) {
        await p.goto(B + '/my-account/', { waitUntil: 'networkidle' });
        await p.fill('#username', 'client'); await p.fill('#password', 'client-pass');
        await Promise.all([p.waitForLoadState('networkidle'), p.click('button[name="login"]')]); logged = true;
      }
      if (name === 'acc-view-order') continue;
      errs.length = 0;
      const resp = await p.goto(path.startsWith('http') ? path : B + path, { waitUntil: 'networkidle' });
      await p.waitForFunction(() => !document.querySelector('.wc-block-components-skeleton__element, .wc-block-components-loading-mask'), null, { timeout: 30000 }).catch(() => {});
      await p.waitForTimeout(300);
      const html = await p.content();
      const info = await p.evaluate(() => ({
        overflow: document.documentElement.scrollWidth - innerWidth,
        dir: document.documentElement.dir, header: !!document.querySelector('header.ds-header'),
        footer: !!document.querySelector('footer.ds-footer'), mains: document.querySelectorAll('main').length,
        h1: document.querySelectorAll('h1').length,
      }));
      await p.evaluate(axeSrc);
      const axe = (await p.evaluate(async () => (await axe.run(document, { runOnly: ['wcag2a', 'wcag2aa', 'wcag21aa', 'best-practice'] })).violations.map(v => ({ id: v.id, n: v.nodes.length, t: v.nodes[0].target.join(' ').slice(0, 80) })))).filter(v => !ignored(v));
      const pro = /elementor-pro|elementor_pro|ElementorPro/i.test(html);
      await p.screenshot({ path: `${OUT}/${LABEL}-${name}-${vn}.png`, fullPage: true });
      const status = resp.status();
      const problems = [];
      if (status !== expect) problems.push('status ' + status);
      if (info.overflow > 0) problems.push('overflow ' + info.overflow);
      if (info.dir !== 'rtl') problems.push('dir ' + info.dir);
      if (!info.header || !info.footer) problems.push('header/footer missing');
      if (info.mains < 1) problems.push('no <main>');
      if (pro) problems.push('ELEMENTOR PRO REFERENCE');
      if (errs.length) problems.push('js: ' + errs.join(' | '));
      if (axe.length) problems.push('axe: ' + axe.map(a => `${a.id}x${a.n} @${a.t}`).join(', '));
      if (problems.length) failures++;
      rows.push(`${vn} ${name.padEnd(20)} ${problems.length ? 'FAIL ' + problems.join('; ') : 'ok'}`);
    }
    await ctx.close();
  }
  await b.close();
  console.log(rows.join('\n'));
  console.log(failures ? `\n[${LABEL}] ${failures} FAILED` : `\n[${LABEL}] ALL ${rows.length} CHECKS PASSED`);
  process.exit(failures ? 1 : 0);
})();
